phương trình tuyến tính

```cpp
void TRY(int k){
    for(int  v = 1; v <= M-T - n+k; v++){
       if(check(v,k)){
           X[k] = v;
           T = T + X[k];// update incrementally
           if(k == n) solution();
           else TRY(k+1);
           T = T - X[k];// recover when backtracking
       }
    }
}
int main(){
    n = 6; M = 15;
    T = 0;
    TRY(1);
}
```

