PRIM(G = (V,E,w)) {
  select a random node s of V;
  for(v  V) {
     d(v) = w(s,v); near(v) = s;
  }
  ET = {}; VT = {s};
  while(|VT|  |V|) {
    v = select a node  V \ VT having minimum d(v);
    VT = VT{v}; ET = ET  {(v, near(v))};
    for(x  V \ VT) {
      if(d(x) > w(x,v) {
       d(x) = w(x,v);
       near(x) = v;
      }
    }
  }
  return (VT, ET);
}
