void init(){
    for(int v = 1; v <= n; v++) visited[v] = false;
}
void solve(){
    init();
    t = 0;
    for(int s = 1; s <= n; s++){
       if(!visited[s]){
           dfs(s,-1);
       }
    }
    cout << "bridges = ";
    for(int i = 0; i < bridges.size(); i++){
       cout << "(" << bridges[i].first << "," << bridges[i].second << ") ";
    }
}
int main(){
    input();
    solve();
}
